  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (database_id, name),
  FOREIGN KEY (database_id) REFERENCES databases(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS ix_db_tables_database_id ON db_tables (database_id);
CREATE TRIGGER IF NOT EXISTS trg_db_tables_updated_at
AFTER UPDATE ON db_tables
FOR EACH ROW
BEGIN
  UPDATE db_tables SET updated_at = CURRENT_TIMESTAMP WHERE id = NEW.id;
END;

-- Synced column metadata for a table.
CREATE TABLE IF NOT EXISTS db_columns (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  db_table_id INTEGER NOT NULL,
  name TEXT NOT NULL,
