CREATE TRIGGER IF NOT EXISTS trg_db_columns_updated_at
AFTER UPDATE ON db_columns
FOR EACH ROW
BEGIN
  UPDATE db_columns SET updated_at = CURRENT_TIMESTAMP WHERE id = NEW.id;
END;

-- Business context for the AI, scoped at several levels.
CREATE TABLE IF NOT EXISTS instructions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  workspace_id INTEGER NOT NULL,
  scope TEXT NOT NULL CHECK (scope IN ('workspace', 'database', 'table', 'column')),
  database_id INTEGER,
  db_table_id INTEGER,
  target_column TEXT,
  content TEXT NOT NULL,
  created_by INTEGER,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
  FOREIGN KEY (database_id) REFERENCES databases(id) ON DELETE SET NULL,
  FOREIGN KEY (db_table_id) REFERENCES db_tables(id) ON DELETE SET NULL,
  FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS ix_instructions_workspace_id ON instructions (workspace_id);
CREATE TRIGGER IF NOT EXISTS trg_instructions_updated_at
AFTER UPDATE ON instructions
FOR EACH ROW
BEGIN
  UPDATE instructions SET updated_at = CURRENT_TIMESTAMP WHERE id = NEW.id;
END;

