CREATE TRIGGER IF NOT EXISTS trg_env_keys_updated_at
AFTER UPDATE ON env_keys
FOR EACH ROW
BEGIN
  UPDATE env_keys SET updated_at = CURRENT_TIMESTAMP WHERE id = NEW.id;
END;

-- Configured AI agents (provider + model + prompt).
CREATE TABLE IF NOT EXISTS agents (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  workspace_id INTEGER NOT NULL,
  name TEXT NOT NULL,
  provider TEXT NOT NULL CHECK (provider IN ('openai', 'claude', 'gemini', 'openrouter')),
  model TEXT,
