  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL,
  FOREIGN KEY (database_id) REFERENCES databases(id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS ix_suggestions_workspace_id ON suggestions (workspace_id);
CREATE TRIGGER IF NOT EXISTS trg_suggestions_updated_at
AFTER UPDATE ON suggestions
FOR EACH ROW
BEGIN
  UPDATE suggestions SET updated_at = CURRENT_TIMESTAMP WHERE id = NEW.id;
END;

-- Generic key/value metadata attached to any entity.
CREATE TABLE IF NOT EXISTS metadata (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  workspace_id INTEGER,
  entity_type TEXT NOT NULL,
  entity_id INTEGER,
  key TEXT NOT NULL,
  value JSON CHECK (value IS NULL OR json_valid(value)),
