-- Query-safety rules: allow/block statement types per workspace/db.
CREATE TABLE IF NOT EXISTS query_rules (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  workspace_id INTEGER NOT NULL,
  database_id INTEGER,
  statement_type TEXT NOT NULL,
  action TEXT NOT NULL CHECK (action IN ('allow', 'block')),
  enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (workspace_id, database_id, statement_type),
  FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
  FOREIGN KEY (database_id) REFERENCES databases(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS ix_query_rules_workspace_id ON query_rules (workspace_id);
CREATE TRIGGER IF NOT EXISTS trg_query_rules_updated_at
AFTER UPDATE ON query_rules
FOR EACH ROW
BEGIN
  UPDATE query_rules SET updated_at = CURRENT_TIMESTAMP WHERE id = NEW.id;
END;

-- Append-only audit of user actions.
CREATE TABLE IF NOT EXISTS user_logs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  workspace_id INTEGER,
  user_id INTEGER,
  action TEXT NOT NULL,
  target_type TEXT,
  target_id TEXT,
  ip_address TEXT,
  metadata JSON CHECK (metadata IS NULL OR json_valid(metadata)),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE SET NULL,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS ix_user_logs_workspace_id ON user_logs (workspace_id);
CREATE INDEX IF NOT EXISTS ix_user_logs_user_id ON user_logs (user_id);
CREATE INDEX IF NOT EXISTS ix_user_logs_created_at ON user_logs (created_at);

-- Append-only system events / errors.
CREATE TABLE IF NOT EXISTS system_logs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  level TEXT NOT NULL DEFAULT 'info' CHECK (level IN ('debug', 'info', 'warn', 'error')),
  source TEXT,
  message TEXT NOT NULL,
  metadata JSON CHECK (metadata IS NULL OR json_valid(metadata)),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS ix_system_logs_level ON system_logs (level);
CREATE INDEX IF NOT EXISTS ix_system_logs_created_at ON system_logs (created_at);
